func:
// Validation des données reçues du récepteur ESP32

if (!msg.payload || typeof msg.payload !== 'object') {
    node.error('Payload invalide ou vide');
    node.status({fill:'red', shape:'ring', text:'Données invalides'});
    return null;
}

let data = msg.payload;

// Extraction température (compatibilité avec différents formats)
let temperature = null;
if (data.temperature !== undefined) {
    temperature = parseFloat(data.temperature);
} else if (data.temp !== undefined) {
    temperature = parseFloat(data.temp);
} else if (data.avgTemp !== undefined) {
    temperature = parseFloat(data.avgTemp);
}

// Extraction humidité
let humidity = null;
if (data.humidity !== undefined) {
    humidity = parseFloat(data.humidity);
} else if (data.humidite !== undefined) {
    humidity = parseFloat(data.humidite);
} else if (data.avgHumidity !== undefined) {
    humidity = parseFloat(data.avgHumidity);
}

// Validation des valeurs
if (isNaN(temperature) || isNaN(humidity)) {
    node.error('Température ou humidité non numériques: T=' + temperature + ' H=' + humidity);
    node.status({fill:'red', shape:'ring', text:'Valeurs NaN'});
    return null;
}

// Vérification plausibilité
if (temperature < -40 || temperature > 80) {
    node.warn('Température hors plage: ' + temperature);
    node.status({fill:'yellow', shape:'ring', text:'T hors plage: ' + temperature});
    return null;
}

if (humidity < 0 || humidity > 100) {
    node.warn('Humidité hors plage: ' + humidity);
    node.status({fill:'yellow', shape:'ring', text:'H hors plage: ' + humidity});
    return null;
}

// Extraction état AC
const modes = ['Auto', 'Cool', 'Dry', 'Heat', 'Fan'];
let auto_mode = data.auto_mode || false;
let ac_power;

if (auto_mode) {
    ac_power = temperature > 25; // Auto : ON si temp dépasse seuil
} else {
    ac_power = data.ac_power || false; // Manuel : respecter ESP32
}

let ac_mode = modes[data.ac_mode] || 'Cool';
let ac_state = ac_power ? ('ON | ' + ac_mode) : 'OFF';

// Métadonnées
let now = new Date();

// Construction payload normalisé
msg.payload = {
    // Données capteurs
    temperature: Math.round(temperature * 10) / 10,
    humidity: Math.round(humidity * 10) / 10,

    // État climatiseur
    ac_state: ac_state,
    ac_power: ac_power,
    ac_mode: ac_mode,
    ac_temp_set: data.ac_temp_set || 23,
    ac_fan_speed: data.ac_fan_speed || 0,
    auto_mode: auto_mode,

    // Données capteurs détaillées
    local_temp: data.local_temp || null,
    local_humidity: data.local_humidity || null,
    remote_temp: data.remote_temp || null,
    remote_humidity: data.remote_humidity || null,

    // Métadonnées
    device_id: data.device_id || 'ESP32_AC_001',
    timestamp: data.ts_ms || now.getTime(),
    received_at: now.toISOString(),
    date_formatted: now.toLocaleString('fr-FR'),

    // Données brutes
    raw: data
};

// Alertes selon seuils réels du projet
if (msg.payload.temperature > 26) {
    msg.payload.alerte = '🔴 Temp trop haute: ' + msg.payload.temperature + '°C';
    msg.payload.alerte_type = 'temp_high';
} else if (msg.payload.temperature < 20) {
    msg.payload.alerte = '❄️ Temp trop basse: ' + msg.payload.temperature + '°C';
    msg.payload.alerte_type = 'temp_low';
} else if (msg.payload.humidity > 75) {
    msg.payload.alerte = '🌊 Humidité élevée: ' + msg.payload.humidity + '%';
    msg.payload.alerte_type = 'humidity_high';
} else if (msg.payload.humidity < 25) {
    msg.payload.alerte = '🟥 Humidité basse: ' + msg.payload.humidity + '%';
    msg.payload.alerte_type = 'humidity_low';
} else {
    msg.payload.alerte = '✅ Tout est normal';
    msg.payload.alerte_type = 'ok';
}

// Statut visuel du nœud
node.status({
    fill: msg.payload.alerte_type === 'ok' ? 'green' : 'yellow',
    shape: 'dot',
    text: 'T=' + msg.payload.temperature + '°C H=' + msg.payload.humidity + '%'
});

return msg;

// Stocker les dernières données dans le contexte flow
flow.set('lastData', msg.payload);
flow.set('lastUpdate', Date.now());

// Récupérer le statut backup depuis le contexte global
var backupStatus = global.get("backupStatus") || "BACKUP_OFF";

// Historique des 100 dernières valeurs
let history = flow.get('dataHistory') || [];
history.push({
    temp: msg.payload.temperature,
    hum: msg.payload.humidity,
    backup: backupStatus,        // ← AJOUTÉ
    ts: Date.now()
});

// Garder seulement les 100 dernières
if (history.length > 100) {
    history = history.slice(-100);
}
flow.set('dataHistory', history);

return msg;

const modeIcons = ['🔄 Auto', '❄️ Mode Froid', '💧 Mode Sec', '🔥 Mode Chaud', '🌀 Ventilateur'];
const speeds = ['Auto', 'Low', 'Medium', 'High'];

// Lire l'état RÉEL depuis l'ESP32 uniquement
let ac_power = msg.payload.ac_power || false;
let ac_mode_index = msg.payload.raw ? msg.payload.raw.ac_mode : 1;
let ac_temp_set = msg.payload.ac_temp_set || 23;
let ac_fan = speeds[msg.payload.raw ? msg.payload.raw.ac_fan_speed : 0] || 'Auto';
let auto_mode = msg.payload.auto_mode || false;

let acPower = ac_power ? 'ON' : 'OFF';
let acMode = modeIcons[ac_mode_index] || '❄️ Mode Froid';

let bgColor;
if (!ac_power) {
    bgColor = 'linear-gradient(135deg, #636e72 0%, #b2bec3 100%)';
} else if (ac_mode_index === 1) {
    bgColor = 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)';
} else if (ac_mode_index === 3) {
    bgColor = 'linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)';
} else if (ac_mode_index === 2) {
    bgColor = 'linear-gradient(135deg, #00b894 0%, #00cec9 100%)';
} else {
    bgColor = 'linear-gradient(135deg, #a29bfe 0%, #6c5ce7 100%)';
}

msg.payload = {
    power: acPower,
    mode: acMode,
    temperature: msg.payload.temperature,
    ac_temp_set: ac_temp_set,
    fan_speed: ac_fan,
    autoMode: auto_mode ? 'Activé' : 'Désactivé',
    isOn: ac_power,
    bgColor: bgColor
};

node.status({
    fill: ac_power ? 'green' : 'grey',
    shape: 'dot',
    text: 'AC ' + acPower + ' | ' + acMode
});

return msg;

const COOLDOWN_MS = 60000; // 1 minute

let temp = msg.payload.temperature;
let hum = msg.payload.humidity;
let tempKey = Math.round(temp);
let humKey = Math.round(hum);

// ← AJOUTÉ : Récupérer statut backup
let backupActif = msg.payload.backup_actif || false;
let lastBackupState = flow.get('lastBackupState') || false;

let lastAlertTemp = flow.get('lastAlertTemp') || 0;
let lastAlertHum = flow.get('lastAlertHum') || 0;
let lastAlertTime = flow.get('lastAlertTime') || 0;

let now = Date.now();

let tempChanged = Math.abs(tempKey - lastAlertTemp) >= 1;
let humChanged = Math.abs(humKey - lastAlertHum) >= 2;
let cooldownPassed = (now - lastAlertTime) > COOLDOWN_MS;

// ← AJOUTÉ : Backup changé d'état → passer immédiatement sans cooldown
let backupChanged = (backupActif !== lastBackupState);

if (backupChanged) {
    flow.set('lastBackupState', backupActif);
    flow.set('lastAlertTime', now);
    node.status({fill:'red', shape:'dot', text:'BACKUP - Email envoyé!'});
    return msg;
}

if ((tempChanged || humChanged) && cooldownPassed) {
    flow.set('lastAlertTemp', tempKey);
    flow.set('lastAlertHum', humKey);
    flow.set('lastAlertTime', now);
    node.status({fill:'green', shape:'dot', text:'Message passé'});
    return msg;
}

node.status({fill:'yellow', shape:'ring', text:'Cooldown actif'});
return null;

const THRESHOLDS = {
    TEMP_MIN: 20,
    TEMP_MAX: 26,
    HUM_MIN: 25,
    HUM_MAX: 75
};

let temp = msg.payload.temperature;
let hum = msg.payload.humidity;
let ac_power = msg.payload.ac_power;
let ac_mode = msg.payload.ac_mode;
let auto_mode = msg.payload.auto_mode;

// ← AJOUTÉ : Récupérer statut backup
let backupStatus = global.get("backupStatus") || "BACKUP_OFF";
let backupActif = (backupStatus === "BACKUP_ACTIF");

let alerts = [];
let alertLevel = 'normal';

// ← AJOUTÉ : Vérifier backup EN PREMIER (priorité maximale)
if (backupActif) {
    alerts.push(`🚨 CRITIQUE: Climatiseur backup déclenché ! Clim principal en panne.`);
    alertLevel = 'critical';
}

if (temp >= THRESHOLDS.TEMP_MAX) {
    alerts.push(`🔥 Température élevée: ${temp.toFixed(1)}°C (MAX: ${THRESHOLDS.TEMP_MAX}°C)`);
    alertLevel = 'critical';
} else if (temp < THRESHOLDS.TEMP_MIN) {
    alerts.push(`❄️ Température basse: ${temp.toFixed(1)}°C (MIN: ${THRESHOLDS.TEMP_MIN}°C)`);
    alertLevel = alertLevel === 'critical' ? 'critical' : 'warning';
}

if (hum > THRESHOLDS.HUM_MAX) {
    alerts.push(`🌊 Humidité élevée: ${hum.toFixed(1)}% (MAX: ${THRESHOLDS.HUM_MAX}%)`);
    alertLevel = alertLevel === 'critical' ? 'critical' : 'warning';
} else if (hum < THRESHOLDS.HUM_MIN) {
    alerts.push(`🟥 Humidité basse: ${hum.toFixed(1)}% (MIN: ${THRESHOLDS.HUM_MIN}%)`);
    alertLevel = alertLevel === 'critical' ? 'critical' : 'warning';
}

msg.payload = {
    alerts: alerts,
    hasAlert: alerts.length > 0,
    level: alertLevel,
    temperature: temp,
    humidity: hum,
    ac_power: ac_power,
    ac_mode: ac_mode,
    auto_mode: auto_mode,
    backup_actif: backupActif,        // ← AJOUTÉ
    backup_status: backupStatus       // ← AJOUTÉ
};

return msg;

var alerts = msg.payload.alerts || [];
var hasAlert = msg.payload.hasAlert || false;
var level = msg.payload.level || 'normal';
var temp = msg.payload.temperature || 0;
var hum = msg.payload.humidity || 0;

// ← AJOUTÉ : Récupérer statut backup
var backupActif = msg.payload.backup_actif || false;
var backupStatus = msg.payload.backup_status || "BACKUP_OFF";

msg.payload = {
    hasAlert: hasAlert,
    level: level,
    alerts: alerts,
    temperature: temp,
    humidity: hum,
    backup_actif: backupActif,      // ← AJOUTÉ
    backup_status: backupStatus     // ← AJOUTÉ
};

return msg;

// Si le payload est déjà un objet JSON valide, le passer directement
if (typeof msg.payload === 'object' && Object.keys(msg.payload).length > 0) {
    msg.payload = JSON.stringify(msg.payload);
    return msg;
}

let payload = msg.payload;
let command = {};

if (payload === "toggle_power") {
    let currentState = flow.get('acPowerState') || false;
    let newState = !currentState;
    flow.set('acPowerState', newState);
    command = { power: newState ? 1 : 0 };
} else if (payload === "next_mode" || payload === "toggle_mode") {
    let currentMode = flow.get('acMode') || 1;
    currentMode = (currentMode + 1) % 5;
    flow.set('acMode', currentMode);
    command = { mode: currentMode };
} else if (payload === "temp_up") {
    let currentTemp = flow.get('acTemp') || 23;
    if (currentTemp < 30) currentTemp++;
    flow.set('acTemp', currentTemp);
    command = { temperature: currentTemp };
} else if (payload === "temp_down") {
    let currentTemp = flow.get('acTemp') || 23;
    if (currentTemp > 16) currentTemp--;
    flow.set('acTemp', currentTemp);
    command = { temperature: currentTemp };
} else {
    return null; // bloquer les messages inconnus
}

msg.payload = JSON.stringify(command);
msg.topic = "esp32/ac/control";
return msg;

const lastUpdate = new Date().toLocaleString('fr-FR');

msg.payload = `<div style="padding:12px; background:linear-gradient(135deg, #3dbb6e 0%, #00b09b 100%); border-radius:8px; text-align:center;">
    <div style="font-size:16px; color:#fff;">✅ ESP32 Connecté</div>
    <div style="font-size:11px; opacity:0.9; margin-top:3px; color:#fff;">MAJ: ${lastUpdate}</div>
</div>`;

return msg;

let temp = msg.payload.temperature;
let hum = msg.payload.humidity;
let autoMode = msg.payload.auto_mode ? 'Activé' : 'Désactivé';

let backupStatus = global.get("backupStatus") || "BACKUP_OFF";
let backupActif = (backupStatus === "BACKUP_ACTIF");

const TEMP_MIN = 20;
const TEMP_MAX = 26;
const HUM_MIN = 25;
const HUM_MAX = 75;

let color, icon, title, description, gradient;
let acStatus, acMode;

if (backupActif) {
    color = "#E74C3C";
    icon = "🚨";
    title = "CRITIQUE : Climatiseur Backup Déclenché";
    description = "Le climatiseur principal est en panne ou inefficace. Le backup a été activé automatiquement.";
    gradient = "linear-gradient(135deg, #E74C3C 0%, #922B21 100%)";
    acStatus = 'BACKUP ON ⚠️';
    acMode = 'Backup actif';
} else if (temp >= TEMP_MAX) {
    color = "#E74C3C";
    icon = "🔥";
    title = "Alerte : Température élevée";
    description = "Température supérieure ou égale à 26°C. Mode froid activé.";
    gradient = "linear-gradient(135deg, #E74C3C 0%, #C0392B 100%)";
    acStatus = 'ON ✅';
    acMode = 'Mode Froid';
} else if (temp < TEMP_MIN) {
    color = "#3498DB";
    icon = "❄️";
    title = "Alerte : Température basse";
    description = "Température inférieure à 20°C. Mode chaud activé.";
    gradient = "linear-gradient(135deg, #3498DB 0%, #2980B9 100%)";
    acStatus = 'ON ✅';
    acMode = 'Mode Chaud';
} else if (hum > HUM_MAX) {
    color = "#9B59B6";
    icon = "💧";
    title = "Alerte : Humidité élevée";
    description = "Humidité supérieure à 75%. Mode Dry activé.";
    gradient = "linear-gradient(135deg, #9B59B6 0%, #8E44AD 100%)";
    acStatus = 'ON ✅';
    acMode = 'Mode Dry';
} else if (hum < HUM_MIN) {
    color = "#F39C12";
    icon = "🌵";
    title = "Alerte : Humidité faible";
    description = "Humidité inférieure à 25%.";
    gradient = "linear-gradient(135deg, #F39C12 0%, #E67E22 100%)";
    acStatus = msg.payload.ac_power ? 'ON ✅' : 'OFF ❌';
    acMode = msg.payload.ac_mode || '—';
} else {
    node.status({fill:'green', shape:'dot', text:'Normal - pas d email'});
    return null;
}

msg.topic = `${icon} ${title} - Monitoring ESP32`;

msg.payload = `
<div style="font-family: Arial, sans-serif; background:#f4f6f8; padding:20px;">
  <div style="max-width:600px; margin:auto; background:white; border-radius:10px; overflow:hidden; box-shadow:0 4px 10px rgba(0,0,0,0.1);">

    <div style="background:${gradient}; color:white; padding:20px; text-align:center;">
      <h2 style="margin:0;">${icon} ${title}</h2>
    </div>

    <div style="padding:20px; color:#333;">
      <p>${description}</p>

      <table style="width:100%; border-collapse:collapse;">
        <tr>
          <td><strong>🌡️ Température :</strong></td>
          <td>${temp.toFixed(1)} °C</td>
        </tr>
        <tr>
          <td><strong>💧 Humidité :</strong></td>
          <td>${hum.toFixed(1)} %</td>
        </tr>
        <tr>
          <td><strong>❄️ Climatisation :</strong></td>
          <td>${acStatus} — ${acMode}</td>
        </tr>
        <tr>
          <td><strong>⚙️ Mode Auto :</strong></td>
          <td>${autoMode}</td>
        </tr>
        <tr style="background:${backupActif ? '#FDEDEC' : '#F2F3F4'};">
          <td><strong>🔄 Clim Backup :</strong></td>
          <td style="color:${backupActif ? '#E74C3C' : '#7f8c8d'}; font-weight:bold;">
            ${backupActif ? '⚠️ ACTIF — Panne clim principal !' : '❌ OFF'}
          </td>
        </tr>
      </table>
    </div>

    <div style="background:#ecf0f1; padding:10px; text-align:center; font-size:12px; color:#7f8c8d;">
      ESP32 Monitoring System
    </div>

  </div>
</div>
`;

node.status({fill:'red', shape:'dot', text:'Alerte envoyée: ' + title});
return msg;

const BASE_PATH = 'C:/Users/TPC/Desktop/Stage PFE/PFE Excel';
const SEP = ';';

if (!msg.payload || typeof msg.payload !== 'object') {
    return null;
}

let temp = msg.payload.temperature;
let hum = msg.payload.humidity;

if (temp === undefined || hum === undefined) {
    return null;
}

const pad = n => String(n).padStart(2, '0');
const now = new Date();
const year = now.getFullYear();
const month = pad(now.getMonth() + 1);
const day = pad(now.getDate());
const heure = `${pad(now.getHours())}:${pad(now.getMinutes())}`;

const fmt = n => n.toFixed(2).replace('.', ',');

// Données climatiseur
let acPower = msg.payload.ac_power ? 'ON' : 'OFF';
const modes = ['Auto', 'Cool', 'Dry', 'Heat', 'Fan'];
let acMode = modes[msg.payload.ac_mode] || 'N/A';
let acTemp = msg.payload.ac_temp_set || 'N/A';
let autoMode = msg.payload.auto_mode ? 'ON' : 'OFF';

// ← AJOUTÉ : Récupérer statut backup
let backupStatus = global.get("backupStatus") || "BACKUP_OFF";

const folder = `${BASE_PATH}/${year}-${month}`;
msg.filename = `${folder}/Donnees_${day}.csv`;

let headersWritten = flow.get('csv_headers_' + day) || false;
let out = '';

if (!headersWritten) {
    // ← AJOUTÉ : Colonne Backup_Status dans l'entête
    out += 'Date;Heure;Température (°C);Humidité (%);État AC;Mode AC;Temp Consigne;Mode Auto;Backup Status\n';
    flow.set('csv_headers_' + day, true);
}

// ← AJOUTÉ : ${backupStatus} à la fin de chaque ligne
out += `${day}/${month}/${year}${SEP}${heure}${SEP}${fmt(temp)}${SEP}${fmt(hum)}${SEP}${acPower}${SEP}${acMode}${SEP}${acTemp}${SEP}${autoMode}${SEP}${backupStatus}\n`;

msg.payload = out;
return msg;

msg.payload = JSON.stringify({
    temperature: 22.5 + (Math.random() * 6 - 3),
    humidity: 55 + (Math.random() * 20 - 10),
    local_temp: 22.0,
    local_humidity: 54.0,
    ac_power: false,
    ac_mode: 1,
    ac_temp_set: 23,
    auto_mode: false,
    status: "ok"
});
msg.topic = "esp32/sensors";
return msg;

var payload = msg.payload;

if (typeof payload === "string") {
    try { payload = JSON.parse(payload); } catch(e) { return null; }
}

var backupStatus = payload.backup_status || "BACKUP_OFF";
var backupActive = (backupStatus === "BACKUP_ACTIF");
var temp = payload.temperature || 0;

global.set("backupStatus", backupStatus);
global.set("backupActive", backupActive);

if (backupActive) {
    msg.payload = `<div style="text-align:center; padding:15px; border-radius:10px; background-color:#e74c3c; color:white; font-size:16px; font-weight:bold;">
        🔴 CLIM BACKUP
        <div style="font-size:18px; margin-top:5px; font-weight:900;">ON</div>
        <div style="font-size:12px; margin-top:5px; opacity:0.8;">Temp: ${temp} °C</div>
        <div style="font-size:11px; opacity:0.7;">Seuil critique: 35°C</div>
    </div>`;
} else {
    msg.payload = `<div style="text-align:center; padding:15px; border-radius:10px; background-color:#7f8c8d; color:white; font-size:16px; font-weight:bold;">
        🔴 CLIM BACKUP
        <div style="font-size:18px; margin-top:5px; font-weight:900;">OFF</div>
        <div style="font-size:12px; margin-top:5px; opacity:0.8;">Temp: ${temp} °C</div>
        <div style="font-size:11px; opacity:0.7;">Seuil critique: 35°C</div>
    </div>`;
}

return msg;
